package br.com.onda;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Consumer;import org.json.*;
/** Explicit catalogue searches only; city results require declared coordinates, within 50km. */
final class RadioDirectory {
 static List<RadioStation> search(String term,boolean brazil,Consumer<HttpURLConnection> active)throws Exception{return search(term,brazil,null,active);}
 static String path(String term,boolean brazil,RadioCity city,int offset)throws IOException{String query=term==null?"":term.trim();if(query.length()>120)throw new IOException("Use até 120 caracteres na busca.");return "/json/stations/search?hidebroken=true&order=clickcount&reverse=true&limit="+(city==null?100:500)+(city!=null?"&has_geo_info=true&is_https=true&countrycode="+city.countryCode+"&offset="+Math.max(0,offset):brazil?"&countrycode=BR":"")+(query.isEmpty()?"":"&name="+URLEncoder.encode(query,"UTF-8"));}
 static List<RadioStation> located(String raw,RadioCity city)throws JSONException{JSONArray input=new JSONArray(raw),filtered=new JSONArray();for(int i=0;i<input.length();i++)try{JSONObject o=input.getJSONObject(i);if(city.countryCode.equalsIgnoreCase(o.optString("countrycode"))&&city.distance(o.optDouble("geo_lat",Double.NaN),o.optDouble("geo_long",Double.NaN))<=RadioCity.RADIUS_KM)filtered.put(o);}catch(JSONException ignored){}return RadioStation.read(filtered.toString(),true);}
 static List<RadioStation> search(String term,boolean brazil,RadioCity city,Consumer<HttpURLConnection> active)throws Exception{if(city==null)return RadioStation.read(fetch(path(term,brazil,null,0),active),true);ArrayList<RadioStation> result=new ArrayList<>();Set<String> seen=new HashSet<>();for(int page=0;page<5;page++){String raw=fetch(path(term,brazil,city,page*500),active);for(RadioStation station:located(raw,city))if(seen.add(station.id)){result.add(station);if(result.size()==100)return result;}if(new JSONArray(raw).length()<500)break;}return result;}
 private static String fetch(String path,Consumer<HttpURLConnection> active)throws Exception{Exception last=null;for(String host:new String[]{"de1.api.radio-browser.info","nl1.api.radio-browser.info"}){if(Thread.currentThread().isInterrupted())throw new InterruptedException();HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://"+host+path).openConnection();active.accept(c);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","Onda/0.69.0 (Android radio player)");c.setRequestProperty("Accept","application/json");c.setRequestProperty("Accept-Encoding","gzip");if(c.getResponseCode()!=200)throw new IOException("Catálogo indisponível agora.");InputStream input=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))input=new java.util.zip.GZIPInputStream(input);try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(out.size()+n>2*1024*1024)throw new IOException("Resposta do catálogo muito grande.");out.write(b,0,n);}return out.toString(StandardCharsets.UTF_8.name());}}catch(InterruptedException stop){throw stop;}catch(Exception e){last=e;}finally{if(c!=null)c.disconnect();}}throw new IOException("Não foi possível consultar as rádios. Tente novamente ou abra suas favoritas.",last);}
}
